#!/usr/bin/env python3
"""Sorts a list of [list_of_integers, integer] elements by multiple criteria."""

import ast


def sort_key(element):
    """
    Returns a key tuple for sorting based on three criteria:
    1. Length of the integer list (shorter first)
    2. Lexicographic comparison of the integer lists
    3. The secondary integer value
    """
    int_list = element[0]
    secondary_int = element[1]
    return (len(int_list), int_list, secondary_int)


def main():
    # Read the data from the input file
    with open('/app/task_file/input/data.py', 'r') as f:
        content = f.read()

    # Parse the data list from the Python file
    tree = ast.parse(content)
    data = None
    for node in ast.walk(tree):
        if isinstance(node, ast.Assign):
            for target in node.targets:
                if isinstance(target, ast.Name) and target.id == 'data':
                    data = ast.literal_eval(node.value)

    if data is None:
        raise ValueError("Could not find 'data' variable in input file")

    # Sort using the key function
    sorted_data = sorted(data, key=sort_key)

    # Write the sorted result to the output file
    with open('/app/task_file/output/sorted_result.txt', 'w') as f:
        for element in sorted_data:
            f.write(repr(element) + '\n')


if __name__ == '__main__':
    main()
